package br.com.poolcontrol.financeiro.service;
import br.com.poolcontrol.financeiro.api.dto.ApprovalDecisionRequest; import br.com.poolcontrol.financeiro.domain.FinancialApproval; import br.com.poolcontrol.financeiro.domain.enums.ApprovalStatus; import br.com.poolcontrol.financeiro.exception.BusinessException; import br.com.poolcontrol.financeiro.repository.FinancialApprovalRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.UUID;
@Service @RequiredArgsConstructor public class ApprovalService { private final FinancialApprovalRepository repo;
 @Transactional public FinancialApproval decide(UUID id, ApprovalDecisionRequest r){ if(r.decisao()!=ApprovalStatus.APROVADO && r.decisao()!=ApprovalStatus.REPROVADO) throw new BusinessException("Decisão deve ser APROVADO ou REPROVADO"); var a=repo.findById(id).orElseThrow(()->new BusinessException("Aprovação não encontrada")); if(!a.getEmpresaId().equals(r.empresaId())) throw new BusinessException("Aprovação pertence a outra empresa"); a.setStatus(r.decisao()); a.setAprovadoPor(r.usuarioId()); a.setDecididoEm(OffsetDateTime.now()); a.setObservacoes(r.observacoes()); return repo.save(a); }
}
